1	package com.example.starter.baggage;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	import java.util.HexFormat;
7	import java.util.List;
8	import java.util.concurrent.ConcurrentHashMap;
9	import java.util.concurrent.ConcurrentMap;
10	import java.util.function.Supplier;
11	
12	import com.fasterxml.jackson.databind.ObjectMapper;
13	import org.springframework.dao.DuplicateKeyException;
14	import org.springframework.jdbc.core.JdbcTemplate;
15	import org.springframework.stereotype.Service;
16	import org.springframework.transaction.support.TransactionTemplate;
17	
18	/**
19	 * 幂等去重服务：所有写操作携带全局唯一 requestId。
20	 * 同键同参重放原成功结果，同键异参返回 409；失败请求不占键，
21	 * 业务变更与去重记录在同一事务中原子提交。
22	 */
23	@Service
24	public class IdempotencyService {
25	
26	    private final JdbcTemplate jdbcTemplate;
27	    private final TransactionTemplate transactionTemplate;
28	    private final ObjectMapper objectMapper;
29	    /** 单 JVM 内按 requestId 串行化，数据库唯一主键作为兜底。 */
30	    private final ConcurrentMap<String, Object> locks = new ConcurrentHashMap<>();
31	
32	    public IdempotencyService(JdbcTemplate jdbcTemplate,
33	                              TransactionTemplate transactionTemplate,
34	                              ObjectMapper objectMapper) {
35	        this.jdbcTemplate = jdbcTemplate;
36	        this.transactionTemplate = transactionTemplate;
37	        this.objectMapper = objectMapper;
38	    }
39	
40	    /**
41	     * 在幂等保护下执行写操作。
42	     *
43	     * @param requestId     全局唯一请求标识
44	     * @param operation     操作类型
45	     * @param successStatus 成功响应的 HTTP 状态码（随记录保存，供审计）
46	     * @param payload       请求参数（不含 requestId，调用方需已规范化），用于计算摘要
47	     * @param resultType    成功结果类型，用于重放时反序列化
48	     * @param action        业务动作，成功结果与去重记录在同一事务提交
49	     * @return 已存储的成功结果（重放）或本次执行结果
50	     */
51	    public <T> T execute(String requestId, String operation, int successStatus,
52	                         Object payload, Class<T> resultType, Supplier<T> action) {
53	        String hash = sha256(writeJson(payload));
54	        Object lock = locks.computeIfAbsent(requestId, key -> new Object());
55	        synchronized (lock) {
56	            try {
57	                StoredRequest existing = find(requestId);
58	                if (existing != null) {
59	                    return replay(existing, hash, resultType);
60	                }
61	                try {
62	                    return transactionTemplate.execute(status -> {
63	                        T result = action.get();
64	                        jdbcTemplate.update(
65	                                "INSERT INTO request_log (request_id, operation, request_hash, response_status, response_body)"
66	                                        + " VALUES (?, ?, ?, ?, ?)",
67	                                requestId, operation, hash, successStatus, writeJson(result));
68	                        return result;
69	                    });
70	                } catch (DuplicateKeyException duplicate) {
71	                    // 唯一主键兜底：其他节点已写入同键记录，按已存储结果处理
72	                    StoredRequest stored = find(requestId);
73	                    if (stored == null) {
74	                        throw duplicate;
75	                    }
76	                    return replay(stored, hash, resultType);
77	                }
78	            } finally {
79	                locks.remove(requestId, lock);
80	            }
81	        }
82	    }
83	
84	    private <T> T replay(StoredRequest stored, String hash, Class<T> resultType) {
85	        if (!stored.requestHash().equals(hash)) {
86	            throw ApiException.conflict("requestId 已被使用且请求参数不一致");
87	        }
88	        try {
89	            return objectMapper.readValue(stored.responseBody(), resultType);
90	        } catch (Exception ex) {
91	            throw new IllegalStateException("无法重放已存储的响应", ex);
92	        }
93	    }
94	
95	    private StoredRequest find(String requestId) {
96	        List<StoredRequest> rows = jdbcTemplate.query(
97	                "SELECT request_hash, response_body FROM request_log WHERE request_id = ?",
98	                (rs, rowNum) -> new StoredRequest(rs.getString("request_hash"), rs.getString("response_body")),
99	                requestId);
100	        return rows.isEmpty() ? null : rows.get(0);
101	    }
102	
103	    private String writeJson(Object value) {
104	        try {
105	            return objectMapper.writeValueAsString(value);
106	        } catch (Exception ex) {
107	            throw new IllegalArgumentException("请求参数无法序列化", ex);
108	        }
109	    }
110	
111	    private static String sha256(String text) {
112	        try {
113	            MessageDigest digest = MessageDigest.getInstance("SHA-256");
114	            return HexFormat.of().formatHex(digest.digest(text.getBytes(StandardCharsets.UTF_8)));
115	        } catch (NoSuchAlgorithmException ex) {
116	            throw new IllegalStateException("SHA-256 不可用", ex);
117	        }
118	    }
119	
120	    private record StoredRequest(String requestHash, String responseBody) {
121	    }
122	}
