        assertThat(records).isZero();

        // 补到后整批可成功
        recover("BAG_SHORT", "LEG1", "SHA").andExpect(status().isOk());
        load("LEG2", 1, List.of("BAG_OK", "BAG_SHORT")).andExpect(status().isOk())
                .andExpect(jsonPath("$.loaded", contains("BAG_OK", "BAG_SHORT")));
