private DwellTimeoutCheckResponse doDwellTimeoutCheck(String station, DwellTimeoutCheckRequest request) {
    Long maxDwell = findDwellLimit(station);
    if (maxDwell == null) throw 422 缺配置;
    dedupe check;
    Instant now = clock.get();
    List<DwellCheckItem> items = new ArrayList<>();
    for (String bagTag : sorted) {
        BagRow bag = lockBag(bagTag);
        if (bag == null) throw 422;
        DwellRecordRow record = findLatestDwellRecord(bagTag);
        if (record == null || !record.station().equals(station) || record.arrivedAt() == null) {
            throw ApiException.unprocessable("行李 " + bagTag + " 在 " + station + " 的到达时刻缺失");
        }
        if (DWELL_EXCEEDED_STATUS.equals(record.status())) {
            throw ApiException.conflict("行李 " + bagTag + " 已判定超时，不得重复判定");
        }
        if (!DWELL_OPEN.equals(record.status())) {
            throw ApiException.unprocessable("行李 " + bagTag + " 滞留记录状态为 " + record.status() + "，不可判定");
        }
        long dwellMinutes = Duration.between(record.arrivedAt(), now).toMinutes();
        if (dwellMinutes >= maxDwell) {
            jdbcTemplate.update("UPDATE dwell_record SET status = ?, exceeded_at = ? WHERE id = ?",
                    EXCEEDED, odt(now), record.id());
            jdbcTemplate.update("UPDATE bag SET status = ? WHERE bag_tag = ?", BAG_DWELL_EXCEEDED, bagTag);
            insertDwellEvent(bagTag, DVT_EXCEEDED, station, request.operator(), null, null);
            items.add(new DwellCheckItem(bagTag, station, DWELL_EXCEEDED_STATUS, record.arrivedAt().toString(),
                    dwellMinutes, maxDwell, dwellMinutes - maxDwell));
        } else {
            items.add(new DwellCheckItem(bagTag, station, DWELL_OPEN, arrivedAt, dwellMinutes, maxDwell, null));
        }
    }
    return new DwellTimeoutCheckResponse(station, items);
}
