private ReleaseDwellResponse doReleaseDwell(String bagTag, ReleaseDwellRequest request) {
    BagRow bag = lockBag(bagTag);
    if (bag == null) throw 404;
    DwellRecordRow record = findLatestDwellRecord(bagTag);
    if (record == null) throw 422 无滞留记录;
    if (DWELL_RELEASED.equals(record.status())) throw 409 已解除;
    if (!DWELL_EXCEEDED_STATUS.equals(record.status())) throw 422 状态...未超时不可解除;
    if (!BAG_DWELL_EXCEEDED.equals(bag.status())) throw 422 状态不一致;
    ItineraryItem next = nextItinerary(bagTag, bag.nextLegIndex());
    if (next == null || !next.legId().equals(request.nextLegId())) {
        throw ApiException.unprocessable("下一航段 " + request.nextLegId() + " 不属于行李 " + bagTag + " 的行程");
    }
    LegRow leg = findLeg(request.nextLegId());
    if (leg == null) throw 422 下一航段不存在;
    if (!leg.origin().equals(record.station())) throw 422 下一航段始发站与滞留站点不符;
    LegOpsRow ops = findLegOpsConfig(request.nextLegId());
    if (ops == null) throw 422 下一航段缺少运行配置（截止与容量）;
    Instant now = clock.get();
    if (!now.isBefore(ops.loadDeadline())) {
        throw ApiException.unprocessable("已超过装载截止时刻: 实际 " + now + "，要求早于 " + ops.loadDeadline());
    }
    int loadCount = countLoads(request.nextLegId());
    if (loadCount >= ops.maxCapacity()) {
        throw ApiException.unprocessable("下一航段容量不足: 实际已装 " + loadCount + "，要求小于 " + ops.maxCapacity());
    }
    jdbcTemplate.update("UPDATE dwell_record SET status = ?, released_at = ?, reviewer = ?, review_conclusion = ?, next_leg_id = ? WHERE id = ?",
            RELEASED, odt(now), request.reviewer(), request.conclusion(), request.nextLegId(), record.id());
    jdbcTemplate.update("UPDATE bag SET status = ? WHERE bag_tag = ?", BAG_IN_TRANSIT, bagTag);
    insertDwellEvent(bagTag, DVT_RELEASED, record.station(), request.reviewer(), request.nextLegId(), request.conclusion());
    return new ReleaseDwellResponse(bagTag, BAG_IN_TRANSIT, request.nextLegId(), now.toString(), request.reviewer());
}
